// Stream is the video option stream: Deliver an HLS or DASH stream (as the m3u8 or mpd extension does) with these renditions (at most 8; none: the configured ladder). Rungs above the source are dropped.
//
// URL names: stream, st (short: st); arguments protocol:height…; default none (a file).
// milestone M5 (WP-126); scope request.
type Stream struct {
	// Protocol: manifest: HLS (m3u8) or DASH (mpd); one of dash, hls.
	Protocol StreamProtocol
	// Heights: the repeated height arguments (a rendition by the short side of its frame; range 64 to 4320).
	Heights []int
}

// VideoOption returns the option as xtandard.Option stream (unset trailing arguments are left out).
func (o Stream) VideoOption() xtandard.Option {
	args := []xtandard.Arg{o.Protocol}
	if len(o.Heights) > 0 {
		for _, v := range o.Heights {
			args = append(args, v)
		}
		return xtandard.Option{Name: "stream", Args: args}
	}
	return xtandard.Option{Name: "stream", Args: core.Trim(args, 1)}
}

// Timecode is the video option timecode: Draw the output's running time (FFmpeg drawtext with a fixed expansion).
